function schema(page, crumbs, type='WebPage') {
  return JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'Organization','@id':orgId,name:'Timpson Drafting & Design',url:base,telephone:'+1-435-319-5311',email:publicEmail,address:{'@type':'PostalAddress',streetAddress:'10 Central St Suite 205',addressLocality:'Colorado City',addressRegion:'AZ',postalCode:'86021',addressCountry:'US'},areaServed:[{'@type':'Country',name:'United States'},{'@type':'AdministrativeArea',name:'Southern Utah'},{'@type':'AdministrativeArea',name:'Arizona Strip'}]},{'@type':type,'@id':`${base}${page.path}#webpage`,url:`${base}${page.path}`,name:page.title,description:page.description,provider:{'@id':orgId},breadcrumb:{'@id':`${base}${page.path}#breadcrumb`}},{'@type':'BreadcrumbList','@id':`${base}${page.path}#breadcrumb`,itemListElement:crumbs.map((c,i)=>({'@type':'ListItem',position:i+1,name:c[0],item:`${base}${c[1]}`}))}]});
}
function layout(page, crumbs, body, type='WebPage', robots='index,follow') {
  const title = page.title.includes('|') ? page.title : (page.title.length < 55 ? `${page.title} | Timpson Drafting` : page.title);
  return `<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><meta name="description" content="${page.description}"><meta name="robots" content="${robots}"><link rel="canonical" href="${base}${page.path}"><meta property="og:type" content="website"><meta property="og:title" content="${title}"><meta property="og:description" content="${page.description}"><meta property="og:url" content="${base}${page.path}"><meta property="og:image" content="${base}/tdd-social-share.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="${base}/tdd-social-share.png"><link rel="stylesheet" href="/site-pages.css"><script type="application/ld+json">${schema(page,crumbs,type)}</script></head><body><a class="skip" href="#main">Skip to content</a><header>${nav}</header><main id="main" class="page-shell"><nav class="breadcrumbs" aria-label="Breadcrumb">${crumbs.map((c,i)=>i===crumbs.length-1?`<span aria-current="page">${c[0]}</span>`:`<a href="${c[1]}">${c[0]}</a><b aria-hidden="true">/</b>`).join('')}</nav>${body}</main>${footer}${mobileActionBar}<script src="/site.js" defer></script></body></html>`;
}
