 const body=`<section class="hero"><p class="eyebrow">Residential drafting service</p><h1>${name}</h1><p>${intro}. The first step is defining the property, intended work, available source information, and local review requirements.</p><div class="actions"><a class="button primary" data-track="service_quote_click" data-service="${slug}" href="${serviceQuoteUrl}">Request a quote for ${name.toLowerCase()}</a><a class="button secondary" data-track="phone_click" href="tel:+14353195311">Call ${phone}</a></div></section><section><h2>Who this service is for</h2><p>This service is for homeowners and residential contractors who need a clearly defined drawing scope before construction or permit review.</p><h2>Typical projects</h2><p>${types}.</p><h2>Typical deliverables</h2><p>${deliverables}. Exact sheets are confirmed in the proposal; “permit-ready” does not guarantee approval.</p></section><section class="two"><div><h2>How the process works</h2><ol><li>Share the project location, goals, files, and timeline.</li><li>Timpson reviews scope and identifies missing information.</li><li>After approval, drawings are developed and reviewed with the client.</li><li>The package is finalized for its agreed use and jurisdiction.</li></ol></div><div><h2>Information needed to quote</h2><ul><li>City, state, and project type</li><li>Approximate size and intended use</li><li>Survey, existing plans, sketches, photos, or measurements</li><li>Known building-department requirements</li><li>Desired schedule and file format</li></ul></div></section><section class="two"><div><h2>Pricing factors</h2><p>Complexity, size, quality of existing information, field measurement, number of revisions, site constraints, required sheets, and outside coordination all affect price.</p></div><div><h2>Timeline factors</h2><p>Schedule depends on scope clarity, client decisions, source-file quality, revision cycles, consultant availability, and jurisdiction feedback. A project-specific estimate belongs in the quote.</p></div></section><section><h2>When an architect or engineer may be required</h2><p>Drafting documents are not a substitute for architecture or engineering services where law, structural conditions, site conditions, or the reviewing jurisdiction requires them. Timpson does not claim here to provide an architectural or engineering stamp. Confirm professional requirements with the local building department before submission.</p></section><section><h2>Related guidance and service areas</h2><div class="link-grid"><a href="/residential-drafting-services/">Residential drafting overview</a><a href="/permit-drawing-services/">Permit drawing services</a><a href="/resources/what-is-included-in-permit-ready-plans/">What permit-ready plans include</a><a href="/service-areas/">Where drafting service is available</a></div></section><section><h2>Frequently asked questions</h2><details><summary>Can this work be completed remotely?</summary><p>Often, when reliable measurements, photos, plans, surveys, and jurisdiction details are available. Existing-condition projects may require field verification.</p></details><details><summary>What should I send first?</summary><p>Send the project city and state, intended work, approximate size, timeline, and any existing plans, photos, sketches, or measurements.</p></details><details><summary>Does a drawing package guarantee a permit?</summary><p>No. The local authority reviews the submission and may require revisions, engineering, or other professional documentation.</p></details></section><section class="cta"><h2>Discuss your project</h2><p>Share the core details for a project-specific scope and quote.</p><a class="button primary" data-track="service_quote_click" data-service="${slug}" href="${serviceQuoteUrl}">Request a quote</a></section>`;
 write(slug,layout(page,[['Home','/'],['Services','/services/'],[name,page.path]],body,'Service'));
