const bundle=`<section class="plan-bundle"><h2>One price. The whole plan.</h2><div class="two"><div><p class="bundle-label">Core drawing set</p><h3>The TDD Set</h3><ul><li>Floor plans</li><li>Elevations</li><li>Sections</li><li>Foundation</li><li>Framing</li><li>Roof and site plans</li></ul></div><div class="bundle-included"><p class="bundle-label">Included</p><h3>Build-Ready Planning</h3><ul><li>Manual J load calculation and duct layout</li><li>Electrical layout</li><li>Plumbing layout</li><li>3D model and walk-through</li></ul></div></div></section>`;
