  return layout(page,[['Home','/'],['Services','/services/'],[page.h1,page.path]],`<section class="hero service-hero"><div><p class="eyebrow">Residential drafting service</p><h1>${page.h1}</h1><p>${page.subhead}</p><div class="actions"><a class="button primary" href="/quote/">Request a Quote</a></div></div>${heroMedia}</section>${bundle}<section><h2>Built around your project</h2><ul>${points.map(point=>`<li>${point}</li>`).join('')}</ul></section>${evidenceSection}${relatedSection}${processSection}<section class="cta"><p>${transparency}</p><h2>Let’s plan it right.</h2><a class="button primary" href="/quote/">Request a Quote</a></section>`,'Service');
