const buildReadyBody=`<section class="hero"><p class="eyebrow">Included with every TDD Set</p><h1>Build-Ready Planning</h1><p>Mechanical, electrical, plumbing and 3D coordination—planned before construction begins.</p><div class="actions"><a class="button primary" href="/quote/">Request a Quote</a></div></section>
<section class="build-ready-intro"><p class="eyebrow">The complete package</p><h2>Four coordinated layers. One clear plan.</h2><p>TDD carries the home beyond floor plans and elevations so major systems can be considered together instead of improvised in the field.</p></section>
<section class="build-ready-grid">
  <article class="build-ready-card"><div class="build-ready-media build-ready-media--document"><img src="/project-assets/residential-mechanical-archival.webp" alt="Anonymized archival residential duct-layout sample" width="1400" height="1000" loading="lazy" decoding="async"></div><div class="build-ready-copy"><p class="eyebrow">01 / Mechanical</p><h2>Mechanical plan</h2><p>Manual J load calculation, equipment sizing and a complete duct layout help establish a practical path before installation.</p><p class="sample-note">The image is an anonymized archival duct-layout sample—not a Manual J report or construction document.</p></div></article>
  <article class="build-ready-card"><div class="build-ready-media build-ready-media--document"><img src="/project-assets/electrical-plan.webp" alt="Residential electrical plan showing outlet, lighting and switching layouts" width="1400" height="875" loading="lazy" decoding="async"></div><div class="build-ready-copy"><p class="eyebrow">02 / Electrical</p><h2>Electrical plan</h2><p>Outlet, lighting, switching and panel locations are planned around how the home will actually be used.</p></div></article>
  <article class="build-ready-card"><div class="build-ready-media build-ready-media--document"><img src="/project-assets/plumbing-plan.webp" alt="Residential water-supply plan showing coordinated piping routes" width="1400" height="875" loading="lazy" decoding="async"></div><div class="build-ready-copy"><p class="eyebrow">03 / Plumbing</p><h2>Plumbing plan</h2><p>Fixture locations and supply and drain routes are considered before walls and floors are framed.</p></div></article>
  <article class="build-ready-card"><a class="build-ready-media build-ready-media--video" href="https://youtu.be/d0XkRXjcppw" aria-label="Watch the sample 3D walk-through on YouTube"><img src="/hero-sequence/frame-1.webp" alt="Exterior frame from a TDD 3D walk-through" width="1200" height="675" loading="lazy" decoding="async"><span>Watch sample walk-through</span></a><div class="build-ready-copy"><p class="eyebrow">04 / 3D</p><h2>3D model and walk-through</h2><p>Walk every room before construction and resolve changes on screen rather than on site.</p><a class="button secondary dark-outline" href="/viewer">Open the 3D Viewer</a></div></article>
</section>
<section class="why-grid"><h2>Why it matters</h2><div class="cards"><article class="card"><h3>Calculate before sizing</h3><p>Mechanical decisions start with the home and its actual loads—not a rule-of-thumb guess.</p></article><article class="card"><h3>Change it on paper</h3><p>Decisions resolved before construction are easier to coordinate than field changes.</p></article><article class="card"><h3>Give trades a path</h3><p>Installers receive a coordinated plan to work from instead of filling gaps on site.</p></article></div></section>
<section><h2>What these plans are, and aren’t</h2><p>${transparency}</p></section><section class="cta"><h2>Get the whole plan, not just the walls.</h2><a class="button primary" href="/quote/">Request a Quote</a></section>`;
write('build-ready-planning',layout({path:'/build-ready-planning/',title:'Build-Ready Planning: Manual J, MEP & 3D | TDD',description:'Manual J load calcs, duct, electrical and plumbing layouts plus a 3D walk-through, included with every TDD plan set.'},[['Home','/'],['Build-Ready Planning','/build-ready-planning/']],buildReadyBody));

const aboutBody=`<section class="hero"><p class="eyebrow">About TDD</p><h1>Residential drafting informed by building experience.</h1><p>Timpson Drafting & Design plans homes the way they get built.</p></section><section class="cards about-values"><article class="card"><p class="value-number">01</p><h2>Honesty.</h2><p>Straight answers about what your plans cover, what they don’t and what your project really needs.</p></article><article class="card"><p class="value-number">02</p><h2>Fair price.</h2><p>$1.50 per sq ft with a $3,000 minimum, or by bid for larger projects. No surprise fees.</p></article><article class="card"><p class="value-number">03</p><h2>Revisions until it’s right.</h2><p>Multiple design iterations are built in. After three major revisions we’ll talk scope, but it’s rarely needed.</p></article></section><section class="values-principle"><div><p class="eyebrow">A shared standard</p><h2>Your vision. Our standard.</h2><p>You bring the goals, priorities and picture of how the home should feel. TDD brings practical drafting discipline, trade-aware planning and a clear standard for carrying that vision into drawings people can build from.</p><p class="principle-note">The homeowner remains at the center of the design. TDD provides residential design and drafting—not licensed architectural services.</p></div><figure><img src="/media/tdd-vision-standard.webp" alt="Timpson Drafting artwork showing a sketched home becoming a finished design beneath the words You are the Architect, We are the Standard" width="1200" height="800" loading="lazy" decoding="async"><figcaption>From an idea to a coordinated plan—the vision stays yours.</figcaption></figure></section><section><h2>How we work</h2><p>We work nationwide. Sites are modeled from available satellite data, and on-site visits are negotiable. You’ll see an initial concept in 10 business days, then the design moves at your pace, with revisions back within a work week depending on scope. Construction drawings follow two weeks after approval.</p></section><section><p>${transparency}</p><a class="button primary" href="/quote/">Request a Quote</a></section>`;
const aboutBodyOrdered=aboutBody.replace(/(<section class="cards about-values">[\s\S]*?<\/section>)(<section class="values-principle">[\s\S]*?<\/section>)/,'$2$1');
write('about',layout({path:'/about/',title:'About | Timpson Drafting & Design',description:'Residential drafting informed by building experience. Honest answers, fair pricing and revisions until it’s right.'},[['Home','/'],['About','/about/']],aboutBodyOrdered));

write('privacy',layout({path:'/privacy/',title:'Privacy Policy',description:'How Timpson Drafting & Design collects, uses, protects and manages information submitted through its website and project quote form.'},[['Home','/'],['Privacy','/privacy/']],`<section class="hero"><p class="eyebrow">Legal</p><h1>Privacy Policy</h1><p>How Timpson Drafting uses information submitted through this website.</p></section><section><h2>Information we collect</h2><p>We may collect your name, email address, phone number, project details, uploaded files and other information relevant to your request.</p><h2>How we use information</h2><p>We use submitted information to respond to inquiries, prepare quotes, coordinate scheduling, deliver requested services, maintain business records and improve customer communication. We do not sell personal information.</p><h2>SMS communication</h2><p>If you opt in, message frequency varies and message and data rates may apply. Reply STOP to opt out or HELP for help. Consent is not a condition of purchase.</p><h2>Security and choices</h2><p>We use reasonable safeguards, but no transmission or storage method is completely secure. Contact us to update your information or request that follow-up communication stop.</p><p>Questions: <a href="mailto:${publicEmail}">${publicEmail}</a> or <a href="tel:+14353195311">${phone}</a>.</p></section>`,'WebPage','noindex,follow'));
write('terms',layout({path:'/terms/',title:'Website and SMS Terms',description:'Terms governing use of the Timpson Drafting & Design website, quote requests and optional project-related SMS communication.'},[['Home','/'],['Terms','/terms/']],`<section class="hero"><p class="eyebrow">Legal</p><h1>Website and SMS Terms</h1><p>Terms for website use, quote requests and optional project communication.</p></section><section><h2>Use of this website</h2><p>Provide accurate information when requesting a quote. Form submission does not guarantee project acceptance, scheduling availability or a specific response time.</p><h2>SMS terms</h2><p>If you opt in, you agree to receive conversational messages related to your request. Message frequency varies and message and data rates may apply. Reply STOP to opt out or HELP for help.</p><h2>Communication</h2><p>Email, phone and SMS may be used to answer questions, coordinate scheduling and provide service-related updates. SMS consent is optional and is not a condition of purchase.</p><p>Questions: <a href="mailto:${publicEmail}">${publicEmail}</a> or <a href="tel:+14353195311">${phone}</a>.</p></section>`,'WebPage','noindex,follow'));

